assistant_files.classify-count.mjs:
export function classifyCount(n) {
  if (n < 0) throw new RangeError('count must be nonnegative');
  if (n === 0) return 'zero';
  return 'positive';
}

assistant_files.classify-count.test.mjs:
import { strict as assert } from 'node:assert';
import { classifyCount } from './classify-count.mjs';
assert.equal(classifyCount(1), 'positive');
assert.throws(() => classifyCount(-1), RangeError);
assert.equal(classifyCount(0), 'zero');

